python
def fixedPanelsProofStrip(readings, k):
    a=readings
    out=[]
    s=0
    for i,x in enumerate(a):
        s+=x
        if i>=k: s-=a[i-k]
        if i>=k-1: out.append(s)
    return out


java
class Solution {
  public int[] fixedPanelsProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int s=0;for(int i=0;i<a.length;i++){s+=a[i];if(i>=k)s-=a[i-k];if(i>=k-1)out.add(s);}}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
